"""Throwaway basedpyright repro for AsyncMock attribute typing."""

from dataclasses import dataclass
from unittest.mock import AsyncMock


@dataclass(slots=True)
class Arrangement:
    inbox: int
    sleep: AsyncMock


def via_dataclass(arrangement: Arrangement) -> None:
    arrangement.sleep.assert_awaited_once_with(5.0)


def via_local() -> None:
    sleep = AsyncMock()
    sleep.assert_awaited_once_with(5.0)


def via_annotated_field(arrangement: Arrangement) -> None:
    spy: AsyncMock = arrangement.sleep
    spy.assert_awaited_once_with(5.0)

